{"content": "import mongoose from 'mongoose';
import { config } from './index';

/**
 * 连接 MongoDB 数据库
 */
export const connectDB = async (uri?: string): Promise<void> => {
  const mongoUri = uri || config.mongodbUri;
  try {
    await mongoose.connect(mongoUri);
    if (!config.isTest) {
      console.log(`MongoDB 已连接: ${mongoose.connection.host}`);
    }
  } catch (error) {
    console.error('MongoDB 连接失败:', error);
    process.exit(1);
  }
};

/**
 * 断开数据库连接（用于测试）
 */
export const closeDB = async (): Promise<void> => {
  await mongoose.connection.close();
};

/**
 * 清空数据库（用于测试）
 */
export const clearDB = async (): Promise<void> => {
  const collections = mongoose.connection.collections;
  for (const key in collections) {
    await collections[key].deleteMany({});
  }
};", "path": "D:\123\server\src\config\database.ts"}

{"content": "import mongoose, { Document, Schema } from 'mongoose';
import bcrypt from 'bcryptjs';

/** 地址子文档接口 */
export interface IAddress {
  name: string;
  phone: string;
  province: string;
  city: string;
  district: string;
  detail: string;
  isDefault: boolean;
}

/** 用户接口 */
export interface IUser extends Document {
  email: string;
  password: string;
  nickname: string;
  avatar: string;
  role: 'user' | 'admin';
  addresses: IAddress[];
  isActive: boolean;
  createdAt: Date;
  updatedAt: Date;
  comparePassword(password: string): Promise<boolean>;
}

/** 地址子文档 Schema */
const AddressSchema = new Schema<IAddress>({
  name: { type: String, required: true },
  phone: { type: String, required: true },
  province: { type: String, required: true },
  city: { type: String, required: true },
  district: { type: String, required: true },
  detail: { type: String, required: true },
  isDefault: { type: Boolean, default: false },
});

/** 用户 Schema */
const UserSchema = new Schema<IUser>(
  {
    email: {
      type: String,
      required: true,
      unique: true,
      trim: true,
      lowercase: true,
    },
    password: {
      type: String,
      required: true,
      minlength: 6,
    },
    nickname: {
      type: String,
      required: true,
      trim: true,
    },
    avatar: {
      type: String,
      default: '',
    },
    role: {
      type: String,
      enum: ['user', 'admin'],
      default: 'user',
    },
    addresses: [AddressSchema],
    isActive: {
      type: Boolean,
      default: true,
    },
  },
  {
    timestamps: true,
  }
);

/** 保存前加密密码 */
UserSchema.pre('save', async function (next) {
  if (!this.isModified('password')) return next();
  const salt = await bcrypt.genSalt(10);
  this.password = await bcrypt.hash(this.password, salt);
  next();
});

/** 密码比对方法 */
UserSchema.methods.comparePassword = async function (
  password: string
): Promise<boolean> {
  return bcrypt.compare(password, this.password);
};

/** 序列化时隐藏密码 */
UserSchema.set('toJSON', {
  transform: (_doc: any, ret: any) => {
    delete ret.password;
    return ret;
  },
});

export const User = mongoose.model<IUser>('User', UserSchema);", "path": "D:\123\server\src\models\User.ts"}

