{"content": "import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { config } from '../config';
import { User, IUser } from '../models';

/** 扩展 Request 类型，添加用户信息 */
declare global {
  namespace Express {
    interface Request {
      user?: IUser;
      userId?: string;
    }
  }
}

/** JWT Token 载荷 */
interface JWTPayload {
  userId: string;
  role: string;
}

/**
 * 认证中间件 - 验证 JWT Token
 */
export const authenticate = async (
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.status(401).json({
        success: false,
        message: '未提供认证凭证',
      });
      return;
    }

    const token = authHeader.split(' ')[1];
    const decoded = jwt.verify(token, config.jwtSecret) as JWTPayload;

    const user = await User.findById(decoded.userId);
    if (!user || !user.isActive) {
      res.status(401).json({
        success: false,
        message: '用户不存在或已被禁用',
      });
      return;
    }

    req.user = user;
    req.userId = user._id.toString();
    next();
  } catch (error) {
    res.status(401).json({
      success: false,
      message: '认证凭证无效或已过期',
    });
  }
};

/**
 * 管理员授权中间件
 */
export const authorizeAdmin = (
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  if (!req.user || req.user.role !== 'admin') {
    res.status(403).json({
      success: false,
      message: '无权访问，需要管理员权限',
    });
    return;
  }
  next();
};

/**
 * 可选认证中间件（不强制认证，但若有 token 则解析用户）
 */
export const optionalAuth = async (
  req: Request,
  _res: Response,
  next: NextFunction
): Promise<void> => {
  try {
    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
      const token = authHeader.split(' ')[1];
      const decoded = jwt.verify(token, config.jwtSecret) as JWTPayload;
      const user = await User.findById(decoded.userId);
      if (user && user.isActive) {
        req.user = user;
        req.userId = user._id.toString();
      }
    }
  } catch {
    // Token无效则忽略
  }
  next();
};", "path": "D:\123\server\src\middleware\auth.ts"}

{"content": "/**
 * 生成唯一订单号
 * 格式: SE + 年月日时分秒 + 6位随机数
 * 例如: SE20240101120000123456
 */
export const generateOrderNo = (): string => {
  const now = new Date();
  const dateStr =
    now.getFullYear().toString() +
    String(now.getMonth() + 1).padStart(2, '0') +
    String(now.getDate()).padStart(2, '0') +
    String(now.getHours()).padStart(2, '0') +
    String(now.getMinutes()).padStart(2, '0') +
    String(now.getSeconds()).padStart(2, '0');
  const random = Math.floor(Math.random() * 1000000)
    .toString()
    .padStart(6, '0');
  return `SE${dateStr}${random}`;
};", "path": "D:\123\server\src\utils\order.ts"}

{"content": "import { Router, Request, Response } from 'express';
import { body, validationResult } from 'express-validator';
import jwt from 'jsonwebtoken';
import { User } from '../models';
import { config } from '../config';
import { authenticate } from '../middleware/auth';

const router = Router();

/** 生成 JWT Token */
const generateToken = (userId: string, role: string): string => {
  return jwt.sign({ userId, role }, config.jwtSecret, {
    expiresIn: config.jwtExpiresIn,
  } as jwt.SignOptions);
};

/** 统一校验处理 */
const handleValidationErrors = (req: Request, res: Response): boolean => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    res.status(400).json({
      success: false,
      message: '参数校验失败',
      errors: errors.array().map((e) => e.msg),
    });
    return true;
  }
  return false;
};

/**
 * POST /api/auth/register - 用户注册
 */
router.post(
  '/register',
  [
    body('email').isEmail().withMessage('请输入有效的邮箱地址'),
    body('password')
      .isLength({ min: 6 })
      .withMessage('密码长度至少6位'),
    body('nickname')
      .isLength({ min: 1, max: 30 })
      .withMessage('昵称长度1-30个字符'),
  ],
  async (req: Request, res: Response) => {
    if (handleValidationErrors(req, res)) return;

    try {
      const { email, password, nickname } = req.body;

      const existingUser = await User.findOne({ email });
      if (existingUser) {
        res.status(400).json({
          success: false,
          message: '该邮箱已被注册',
        });
        return;
      }

      const user = await User.create({ email, password, nickname });
      const token = generateToken(user._id.toString(), user.role);

      res.status(201).json({
        success: true,
        data: {
          token,
          user: user.toJSON(),
        },
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        message: '注册失败',
        error: error.message,
      });
    }
  }
);

/**
 * POST /api/auth/login - 用户登录
 */
router.post(
  '/login',
  [
    body('email').isEmail().withMessage('请输入有效的邮箱地址'),
    body('password').notEmpty().withMessage('请输入密码'),
  ],
  async (req: Request, res: Response) => {
    if (handleValidationErrors(req, res)) return;

    try {
      const { email, password } = req.body;

      const user = await User.findOne({ email });
      if (!user) {
        res.status(401).json({
          success: false,
          message: '邮箱或密码错误',
        });
        return;
      }

      if (!user.isActive) {
        res.status(403).json({
          success: false,
          message: '账户已被禁用',
        });
        return;
      }

      const isMatch = await user.comparePassword(password);
      if (!isMatch) {
        res.status(401).json({
          success: false,
          message: '邮箱或密码错误',
        });
        return;
      }

      const token = generateToken(user._id.toString(), user.role);

      res.json({
        success: true,
        data: {
          token,
          user: user.toJSON(),
        },
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        message: '登录失败',
        error: error.message,
      });
    }
  }
);

/**
 * GET /api/auth/profile - 获取用户信息（需认证）
 */
router.get('/profile', authenticate, async (req: Request, res: Response) => {
  try {
    const user = await User.findById(req.userId);
    res.json({
      success: true,
      data: user?.toJSON(),
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '获取用户信息失败',
    });
  }
});

/**
 * PUT /api/auth/profile - 更新用户信息（需认证）
 */
router.put(
  '/profile',
  authenticate,
  [
    body('nickname')
      .optional()
      .isLength({ min: 1, max: 30 })
      .withMessage('昵称长度1-30个字符'),
  ],
  async (req: Request, res: Response) => {
    if (handleValidationErrors(req, res)) return;

    try {
      const { nickname, avatar } = req.body;
      const updateData: any = {};
      if (nickname) updateData.nickname = nickname;
      if (avatar !== undefined) updateData.avatar = avatar;

      const user = await User.findByIdAndUpdate(req.userId, updateData, {
        new: true,
      });

      res.json({
        success: true,
        data: user?.toJSON(),
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        message: '更新用户信息失败',
      });
    }
  }
);

export default router;", "path": "D:\123\server\src\routes\auth.ts"}

{"content": "import { Router, Request, Response } from 'express';
import { body, query, validationResult } from 'express-validator';
import { Product } from '../models';
import { authenticate, authorizeAdmin } from '../middleware/auth';

const router = Router();

/** 统一校验处理 */
const handleValidationErrors = (req: Request, res: Response): boolean => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    res.status(400).json({
      success: false,
      message: '参数校验失败',
      errors: errors.array().map((e) => e.msg),
    });
    return true;
  }
  return false;
};

/**
 * GET /api/products - 获取商品列表（公开）
 */
router.get('/', async (req: Request, res: Response) => {
  try {
    const page = Math.max(1, parseInt(req.query.page as string) || 1);
    const limit = Math.min(50, Math.max(1, parseInt(req.query.limit as string) || 10));
    const skip = (page - 1) * limit;
    const category = req.query.category as string;
    const search = req.query.search as string;
    const sort = req.query.sort as string;
    const minPrice = parseFloat(req.query.minPrice as string);
    const maxPrice = parseFloat(req.query.maxPrice as string);

    // 构建筛选条件
    const filter: any = { status: 'active' };
    if (category) filter.category = category;
    if (!isNaN(minPrice) || !isNaN(maxPrice)) {
      filter.price = {};
      if (!isNaN(minPrice)) filter.price.$gte = minPrice;
      if (!isNaN(maxPrice)) filter.price.$lte = maxPrice;
    }
    if (search) {
      filter.$or = [
        { name: { $regex: search, $options: 'i' } },
        { description: { $regex: search, $options: 'i' } },
      ];
    }

    // 构建排序
    let sortOption: any = { createdAt: -1 };
    if (sort === 'price') sortOption = { price: 1 };
    else if (sort === '-price') sortOption = { price: -1 };
    else if (sort === 'sales') sortOption = { sales: -1 };
    else if (sort === 'createdAt') sortOption = { createdAt: -1 };

    const [products, total] = await Promise.all([
      Product.find(filter).sort(sortOption).skip(skip).limit(limit),
      Product.countDocuments(filter),
    ]);

    res.json({
      success: true,
      data: products,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '获取商品列表失败',
      error: error.message,
    });
  }
});

/**
 * GET /api/products/categories - 获取所有分类（公开）
 */
router.get('/categories', async (_req: Request, res: Response) => {
  try {
    const categories = await Product.distinct('category', { status: 'active' });
    res.json({
      success: true,
      data: categories,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '获取分类失败',
    });
  }
});

/**
 * GET /api/products/:id - 获取商品详情（公开）
 */
router.get('/:id', async (req: Request, res: Response) => {
  try {
    const product = await Product.findById(req.params.id);
    if (!product || product.status === 'inactive') {
      res.status(404).json({
        success: false,
        message: '商品不存在',
      });
      return;
    }

    res.json({
      success: true,
      data: product,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '获取商品详情失败',
    });
  }
});

/**
 * POST /api/products - 创建商品（管理员）
 */
router.post(
  '/',
  authenticate,
  authorizeAdmin,
  [
