{"content": "import { Router, Request, Response } from 'express';
import { body, validationResult } from 'express-validator';
import { CartItem, Product } from '../models';
import { authenticate } from '../middleware/auth';

const router = Router();

/** 使用认证中间件 - 所有购物车接口都需要登录 */
router.use(authenticate);

/** 统一校验处理 */
const handleValidationErrors = (req: Request, res: Response): boolean => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    res.status(400).json({
      success: false,
      message: '参数校验失败',
      errors: errors.array().map((e) => e.msg),
    });
    return true;
  }
  return false;
};

/**
 * GET /api/cart - 获取购物车列表
 */
router.get('/', async (req: Request, res: Response) => {
  try {
    const cartItems = await CartItem.find({ userId: req.userId })
      .populate('productId')
      .sort({ createdAt: -1 });

    // 过滤掉商品已删除或下架的项
    const validItems = cartItems.filter(
      (item) => item.productId && (item.productId as any).status === 'active'
    );

    res.json({
      success: true,
      data: validItems,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '获取购物车失败',
    });
  }
});

/**
 * POST /api/cart - 添加商品到购物车
 */
router.post(
  '/',
  [
    body('productId').notEmpty().withMessage('商品ID不能为空'),
    body('quantity')
      .isInt({ min: 1 })
      .withMessage('数量必须大于0'),
  ],
  async (req: Request, res: Response) => {
    if (handleValidationErrors(req, res)) return;

    try {
      const { productId, quantity } = req.body;

      // 验证商品存在且有效
      const product = await Product.findById(productId);
      if (!product || product.status !== 'active') {
        res.status(404).json({
          success: false,
          message: '商品不存在或已下架',
        });
        return;
      }

      if (product.stock < quantity) {
        res.status(400).json({
          success: false,
          message: `商品库存不足，当前库存: ${product.stock}`,
        });
        return;
      }

      // 检查是否已在购物车中
      const existingItem = await CartItem.findOne({
        userId: req.userId,
        productId,
      });

      if (existingItem) {
        // 更新数量
        const newQuantity = existingItem.quantity + quantity;
        if (newQuantity > product.stock) {
          res.status(400).json({
            success: false,
            message: `购物车中该商品数量已达上限，最大可购买 ${product.stock} 件`,
          });
          return;
        }
        existingItem.quantity = newQuantity;
        await existingItem.save();
        await existingItem.populate('productId');

        res.json({
          success: true,
          data: existingItem,
          message: '购物车已更新',
        });
      } else {
        // 新建购物车项
        const cartItem = await CartItem.create({
          userId: req.userId,
          productId,
          quantity,
        });
        await cartItem.populate('productId');

        res.status(201).json({
          success: true,
          data: cartItem,
          message: '已添加到购物车',
        });
      }
    } catch (error: any) {
      res.status(500).json({
        success: false,
        message: '添加购物车失败',
        error: error.message,
      });
    }
  }
);

/**
 * PUT /api/cart/:id - 修改购物车项数量
 */
router.put(
  '/:id',
  [body('quantity').isInt({ min: 1 }).withMessage('数量必须大于0')],
  async (req: Request, res: Response) => {
    if (handleValidationErrors(req, res)) return;

    try {
      const { quantity } = req.body;
      const cartItem = await CartItem.findOne({
        _id: req.params.id,
        userId: req.userId,
      });

      if (!cartItem) {
        res.status(404).json({
          success: false,
          message: '购物车项不存在',
        });
        return;
      }

      // 验证库存
      const product = await Product.findById(cartItem.productId);
      if (product && quantity > product.stock) {
        res.status(400).json({
          success: false,
          message: `库存不足，当前库存: ${product.stock}`,
        });
        return;
      }

      cartItem.quantity = quantity;
      await cartItem.save();
      await cartItem.populate('productId');

      res.json({
        success: true,
        data: cartItem,
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        message: '更新购物车失败',
      });
    }
  }
);

/**
 * DELETE /api/cart/:id - 删除购物车项
 */
router.delete('/:id', async (req: Request, res: Response) => {
  try {
    const cartItem = await CartItem.findOneAndDelete({
      _id: req.params.id,
      userId: req.userId,
    });

    if (!cartItem) {
      res.status(404).json({
        success: false,
        message: '购物车项不存在',
      });
      return;
    }

    res.json({
      success: true,
      message: '已从购物车移除',
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '删除购物车项失败',
    });
  }
});

/**
 * DELETE /api/cart - 清空购物车
 */
router.delete('/', async (req: Request, res: Response) => {
  try {
    await CartItem.deleteMany({ userId: req.userId });
    res.json({
      success: true,
      message: '购物车已清空',
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '清空购物车失败',
    });
  }
});

