{"content": "import { Router, Request, Response } from 'express';
import { body, validationResult } from 'express-validator';
import { CartItem, Order, Product } from '../models';
import { authenticate } from '../middleware/auth';
import { generateOrderNo } from '../utils/order';

const router = Router();

router.use(authenticate);

/** 统一校验处理 */
const handleValidationErrors = (req: Request, res: Response): boolean => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    res.status(400).json({
      success: false,
      message: '参数校验失败',
      errors: errors.array().map((e) => e.msg),
    });
    return true;
  }
  return false;
};

/**
 * POST /api/orders - 创建订单（从购物车）
 */
router.post(
  '/',
  [
    body('items')
      .isArray({ min: 1 })
      .withMessage('订单至少包含一个商品'),
    body('items.*.productId')
      .notEmpty()
      .withMessage('商品ID不能为空'),
    body('items.*.quantity')
      .isInt({ min: 1 })
      .withMessage('数量必须大于0'),
    body('shippingAddress')
      .notEmpty()
      .withMessage('收货地址不能为空'),
    body('shippingAddress.name')
      .notEmpty()
      .withMessage('收货人姓名不能为空'),
    body('shippingAddress.phone')
      .notEmpty()
      .withMessage('收货人电话不能为空'),
    body('shippingAddress.detail')
      .notEmpty()
      .withMessage('收货地址详情不能为空'),
  ],
  async (req: Request, res: Response) => {
    if (handleValidationErrors(req, res)) return;

    try {
      const { items, shippingAddress } = req.body;

      // 验证商品并计算总价
      const orderItems: any[] = [];
      let totalAmount = 0;

      for (const item of items) {
        const product = await Product.findById(item.productId);
        if (!product || product.status !== 'active') {
          res.status(404).json({
            success: false,
            message: `商品 ${item.productId} 不存在或已下架`,
          });
          return;
        }

        if (product.stock < item.quantity) {
          res.status(400).json({
            success: false,
            message: `商品 "${product.name}" 库存不足，当前库存: ${product.stock}`,
          });
          return;
        }

        orderItems.push({
          productId: product._id,
          productName: product.name,
          price: product.price,
          quantity: item.quantity,
          image: product.images[0] || '',
        });

        totalAmount += product.price * item.quantity;
      }

      // 生成订单号
      const orderNo = generateOrderNo();

      // 创建订单
      const order = await Order.create({
        orderNo,
        userId: req.userId,
        items: orderItems,
        totalAmount,
        shippingAddress,
      });

      // 扣减库存、增加销量
      for (const item of items) {
        await Product.findByIdAndUpdate(item.productId, {
          $inc: { stock: -item.quantity, sales: item.quantity },
        });
      }

      // 清除购物车中已下单的商品
      const productIds = items.map((item: any) => item.productId);
      await CartItem.deleteMany({
        userId: req.userId,
        productId: { $in: productIds },
      });

      res.status(201).json({
        success: true,
        data: order,
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        message: '创建订单失败',
        error: error.message,
      });
    }
  }
);

/**
 * GET /api/orders - 获取订单列表
 */
router.get('/', async (req: Request, res: Response) => {
  try {
    const page = Math.max(1, parseInt(req.query.page as string) || 1);
    const limit = Math.min(50, Math.max(1, parseInt(req.query.limit as string) || 10));
    const skip = (page - 1) * limit;
    const status = req.query.status as string;

    const filter: any = { userId: req.userId };
    if (status) filter.status = status;

    const [orders, total] = await Promise.all([
      Order.find(filter).sort({ createdAt: -1 }).skip(skip).limit(limit),
      Order.countDocuments(filter),
    ]);

    res.json({
      success: true,
      data: orders,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '获取订单列表失败',
    });
  }
});

/**
 * GET /api/orders/all - 获取所有订单（管理员）
 */
router.get('/all', async (req: Request, res: Response) => {
  // 此接口实际应由管理员中间件保护
  try {
    const page = Math.max(1, parseInt(req.query.page as string) || 1);
    const limit = Math.min(50, Math.max(1, parseInt(req.query.limit as string) || 10));
    const skip = (page - 1) * limit;
    const status = req.query.status as string;

    const filter: any = {};
    if (status) filter.status = status;

    const [orders, total] = await Promise.all([
      Order.find(filter)
        .populate('userId', 'email nickname')
        .sort({ createdAt: -1 })
        .skip(skip)
        .limit(limit),
      Order.countDocuments(filter),
    ]);

    res.json({
      success: true,
      data: orders,
      pagination: {
        page,
        limit,
        total,
        pages: Math.ceil(total / limit),
      },
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '获取订单列表失败',
    });
  }
});

/**
 * GET /api/orders/:id - 获取订单详情
 */
router.get('/:id', async (req: Request, res: Response) => {
  try {
    const order = await Order.findOne({
      _id: req.params.id,
      userId: req.userId,
    });

    if (!order) {
      res.status(404).json({
        success: false,
        message: '订单不存在',
      });
      return;
    }

    res.json({
      success: true,
      data: order,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '获取订单详情失败',
    });
  }
});

/**
 * PUT /api/orders/:id/cancel - 取消订单
 */
router.put('/:id/cancel', async (req: Request, res: Response) => {
  try {
    const order = await Order.findOne({
      _id: req.params.id,
      userId: req.userId,
    });

    if (!order) {
      res.status(404).json({
        success: false,
        message: '订单不存在',
      });
      return;
    }

    if (order.status !== 'pending') {
      res.status(400).json({
        success: false,
        message: '只能取消待付款订单',
      });
      return;
    }

    // 恢复库存
    for (const item of order.items) {
      await Product.findByIdAndUpdate(item.productId, {
        $inc: { stock: item.quantity, sales: -item.quantity },
      });
    }

    order.status = 'cancelled';
    await order.save();

    res.json({
      success: true,
      data: order,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '取消订单失败',
    });
  }
});

/**
 * PUT /api/orders/:id/pay - 模拟支付
 */
router.put('/:id/pay', async (req: Request, res: Response) => {
  try {
    const order = await Order.findOne({
      _id: req.params.id,
      userId: req.userId,
    });

    if (!order) {
      res.status(404).json({
        success: false,
        message: '订单不存在',
      });
      return;
    }

    if (order.status !== 'pending') {
      res.status(400).json({
        success: false,
        message: '订单状态不允许支付',
      });
      return;
    }

    order.status = 'paid';
    order.paidAt = new Date();
    await order.save();

    res.json({
      success: true,
      data: order,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '支付失败',
    });
  }
});

/**
 * PUT /api/orders/:id/status - 更新订单状态（管理员）
 */
router.put('/:id/status', async (req: Request, res: Response) => {
  try {
    const { status } = req.body;
    const validStatuses = ['shipped', 'delivered'];

    if (!validStatuses.includes(status)) {
      res.status(400).json({
        success: false,
        message: '无效的订单状态',
      });
      return;
    }

    const order = await Order.findByIdAndUpdate(
      req.params.id,
      { status },
      { new: true }
    );

    if (!order) {
      res.status(404).json({
        success: false,
        message: '订单不存在',
      });
      return;
    }

    res.json({
      success: true,
      data: order,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      message: '更新订单状态失败',
    });
  }
});

