{"content": "import axios, { AxiosInstance, AxiosError, InternalAxiosRequestConfig } from 'axios';
import type {
  ApiResponse,
  PaginatedResponse,
  LoginRequest,
  RegisterRequest,
  User,
  Product,
  CartItem,
  Order,
  AddCartRequest,
  CreateOrderRequest,
} from '../types';

/** 创建 Axios 实例 */
const api: AxiosInstance = axios.create({
  baseURL: '/api',
  timeout: 15000,
  headers: {
    'Content-Type': 'application/json',
  },
});

/** 请求拦截器 - 自动添加 Token */
api.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    const token = localStorage.getItem('token');
    if (token && config.headers) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error: AxiosError) => Promise.reject(error)
);

/** 响应拦截器 - 统一错误处理 */
api.interceptors.response.use(
  (response) => response,
  (error: AxiosError<ApiResponse>) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      // 如果在非登录页面，重定向到登录
      if (window.location.pathname !== '/login') {
        window.location.href = '/login?redirect=' + encodeURIComponent(window.location.pathname);
      }
    }
    return Promise.reject(error);
  }
);

// =========== 认证 API ===========

export const authApi = {
  /** 登录 */
  login: async (data: LoginRequest): Promise<ApiResponse<{ token: string; user: User }>> => {
    const res = await api.post('/auth/login', data);
    return res.data;
  },

  /** 注册 */
  register: async (data: RegisterRequest): Promise<ApiResponse<{ token: string; user: User }>> => {
    const res = await api.post('/auth/register', data);
    return res.data;
  },

  /** 获取用户信息 */
  getProfile: async (): Promise<ApiResponse<User>> => {
    const res = await api.get('/auth/profile');
    return res.data;
  },

  /** 更新用户信息 */
  updateProfile: async (data: Partial<User>): Promise<ApiResponse<User>> => {
    const res = await api.put('/auth/profile', data);
    return res.data;
  },
};

// =========== 商品 API ===========

export const productApi = {
  /** 获取商品列表 */
  getProducts: async (params?: {
    page?: number;
    limit?: number;
    category?: string;
    search?: string;
    sort?: string;
    minPrice?: number;
    maxPrice?: number;
  }): Promise<PaginatedResponse<Product>> => {
    const res = await api.get('/products', { params });
    return res.data;
  },

  /** 获取商品详情 */
  getProductById: async (id: string): Promise<ApiResponse<Product>> => {
    const res = await api.get(`/products/${id}`);
    return res.data;
  },

  /** 获取分类列表 */
  getCategories: async (): Promise<ApiResponse<string[]>> => {
    const res = await api.get('/products/categories');
    return res.data;
  },

  /** 创建商品（管理员） */
  createProduct: async (data: Partial<Product>): Promise<ApiResponse<Product>> => {
    const res = await api.post('/products', data);
    return res.data;
  },

  /** 更新商品（管理员） */
  updateProduct: async (id: string, data: Partial<Product>): Promise<ApiResponse<Product>> => {
    const res = await api.put(`/products/${id}`, data);
    return res.data;
  },

  /** 删除商品（管理员） */
  deleteProduct: async (id: string): Promise<ApiResponse<null>> => {
    const res = await api.delete(`/products/${id}`);
    return res.data;
  },
};

// =========== 购物车 API ===========

export const cartApi = {
  /** 获取购物车 */
  getCart: async (): Promise<ApiResponse<CartItem[]>> => {
    const res = await api.get('/cart');
    return res.data;
  },

  /** 添加商品到购物车 */
  addToCart: async (data: AddCartRequest): Promise<ApiResponse<CartItem>> => {
    const res = await api.post('/cart', data);
    return res.data;
  },

  /** 更新购物车项数量 */
  updateCartItem: async (id: string, quantity: number): Promise<ApiResponse<CartItem>> => {
    const res = await api.put(`/cart/${id}`, { quantity });
    return res.data;
  },

  /** 删除购物车项 */
  removeFromCart: async (id: string): Promise<ApiResponse<null>> => {
    const res = await api.delete(`/cart/${id}`);
    return res.data;
  },

  /** 清空购物车 */
  clearCart: async (): Promise<ApiResponse<null>> => {
    const res = await api.delete('/cart', {});
    return res.data;
  },
};

// =========== 订单 API ===========

export const orderApi = {
  /** 创建订单 */
  createOrder: async (data: CreateOrderRequest): Promise<ApiResponse<Order>> => {
    const res = await api.post('/orders', data);
    return res.data;
  },

  /** 获取订单列表 */
  getOrders: async (params?: {
    page?: number;
    limit?: number;
    status?: string;
  }): Promise<PaginatedResponse<Order>> => {
    const res = await api.get('/orders', { params });
    return res.data;
  },

  /** 获取所有订单（管理员） */
  getAllOrders: async (params?: {
    page?: number;
    limit?: number;
    status?: string;
  }): Promise<PaginatedResponse<Order>> => {
    const res = await api.get('/orders/all', { params });
    return res.data;
  },

  /** 获取订单详情 */
  getOrderById: async (id: string): Promise<ApiResponse<Order>> => {
    const res = await api.get(`/orders/${id}`);
    return res.data;
  },

  /** 取消订单 */
  cancelOrder: async (id: string): Promise<ApiResponse<Order>> => {
    const res = await api.put(`/orders/${id}/cancel`);
    return res.data;
  },

  /** 模拟支付 */
  payOrder: async (id: string): Promise<ApiResponse<Order>> => {
    const res = await api.put(`/orders/${id}/pay`);
    return res.data;
  },

  /** 更新订单状态（管理员） */
  updateOrderStatus: async (id: string, status: string): Promise<ApiResponse<Order>> => {
    const res = await api.put(`/orders/${id}/status`, { status });
    return res.data;
  },
};

export default api;", "path": "D:\123\client\src\services\api.ts"}

{"content": "import { create } from 'zustand';
import type { User } from '../types';
import { authApi } from '../services/api';

/** 认证状态接口 */
interface AuthState {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  isAdmin: boolean;

  /** 初始化 - 从 localStorage 恢复登录状态 */
  init: () => void;

  /** 登录 */
  login: (email: string, password: string) => Promise<void>;

  /** 注册 */
  register: (email: string, password: string, nickname: string) => Promise<void>;

  /** 退出登录 */
  logout: () => void;

  /** 更新用户信息 */
  updateUser: (user: User) => void;

  /** 从服务端刷新用户信息 */
  refreshProfile: () => Promise<void>;
}

/** 认证状态管理 */
export const useAuthStore = create<AuthState>((set, get) => ({
  user: null,
  token: null,
  isAuthenticated: false,
  isLoading: false,
  isAdmin: false,

  init: () => {
    const token = localStorage.getItem('token');
    const userStr = localStorage.getItem('user');
    if (token && userStr) {
      try {
        const user = JSON.parse(userStr) as User;
        set({
          token,
          user,
          isAuthenticated: true,
          isAdmin: user.role === 'admin',
        });
      } catch {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
      }
    }
  },

  login: async (email: string, password: string) => {
    set({ isLoading: true });
    try {
      const res = await authApi.login({ email, password });
      const { token, user } = res.data;
      localStorage.setItem('token', token);
      localStorage.setItem('user', JSON.stringify(user));
      set({
        user,
        token,
        isAuthenticated: true,
        isAdmin: user.role === 'admin',
        isLoading: false,
      });
    } catch (error: any) {
      set({ isLoading: false });
      const message = error.response?.data?.message || '登录失败';
      throw new Error(message);
    }
  },

  register: async (email: string, password: string, nickname: string) => {
    set({ isLoading: true });
    try {
      const res = await authApi.register({ email, password, nickname });
      const { token, user } = res.data;
      localStorage.setItem('token', token);
      localStorage.setItem('user', JSON.stringify(user));
      set({
        user,
        token,
        isAuthenticated: true,
        isAdmin: user.role === 'admin',
        isLoading: false,
      });
    } catch (error: any) {
      set({ isLoading: false });
      const message = error.response?.data?.message || '注册失败';
      throw new Error(message);
    }
  },

  logout: () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    set({
      user: null,
      token: null,
      isAuthenticated: false,
      isAdmin: false,
    });
  },

  updateUser: (user: User) => {
    localStorage.setItem('user', JSON.stringify(user));
    set({ user, isAdmin: user.role === 'admin' });
  },

  refreshProfile: async () => {
    try {
      const res = await authApi.getProfile();
      const user = res.data;
      localStorage.setItem('user', JSON.stringify(user));
      set({ user, isAdmin: user.role === 'admin' });
    } catch {
      get().logout();
    }
  },
}));", "path": "D:\123\client\src\store\authStore.ts"}

