{"content": "import { Card, Tag, Rate } from 'antd';
import { useNavigate } from 'react-router-dom';
import type { Product } from '../types';

interface ProductCardProps {
  product: Product;
}

/** 商品卡片 - 用于商品列表展示 */
export default function ProductCard({ product }: ProductCardProps) {
  const navigate = useNavigate();
  const discount = product.originalPrice
    ? Math.round((1 - product.price / product.originalPrice) * 100)
    : 0;

  return (
    <Card
      className="product-card"
      hoverable
      cover={
        <div style={{ position: 'relative' }}>
          <img alt={product.name} src={product.images?.[0] || 'https://picsum.photos/seed/default/400/400'} />
          {discount > 0 && (
            <Tag color="red" style={{ position: 'absolute', top: 8, left: 8, fontSize: 12 }}>
              -{discount}%
            </Tag>
          )}
        </div>
      }
      onClick={() => navigate(`/products/${product._id}`)}
    >
      <div className="product-name">{product.name}</div>
      <Rate disabled allowHalf value={product.rating} style={{ fontSize: 12, marginBottom: 8 }} />
      <div className="product-price">
        <span className="current-price">¥{product.price.toFixed(2)}</span>
        {product.originalPrice > product.price && (
          <span className="original-price">¥{product.originalPrice.toFixed(2)}</span>
        )}
      </div>
      <div style={{ marginTop: 8, color: '#999', fontSize: 12 }}>
        已售 {product.sales} 件
      </div>
    </Card>
  );
