{"content": "import { useEffect, useState } from 'react';
import { Row, Col, Input, Spin, Typography } from 'antd';
import { SearchOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import ProductCard from '../components/ProductCard';
import { productApi } from '../services/api';
import type { Product } from '../types';

const { Title, Paragraph } = Typography;

const categories = [
  { key: '', label: '全部' },
  { key: '电子产品', label: '📱 电子产品' },
  { key: '服装鞋帽', label: '👔 服装鞋帽' },
  { key: '图书文具', label: '📚 图书文具' },
  { key: '家居生活', label: '🏠 家居生活' },
  { key: '食品饮料', label: '🍔 食品饮料' },
];

export default function HomePage() {
  const navigate = useNavigate();
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState('');

  useEffect(() => {
    const fetchProducts = async () => {
      setLoading(true);
      try {
        const params: any = { limit: 8 };
        if (activeCategory) params.category = activeCategory;
        const res = await productApi.getProducts(params);
        setProducts(res.data);
      } catch {
        // 加载失败时使用空数据
      } finally {
        setLoading(false);
      }
    };
    fetchProducts();
  }, [activeCategory]);

  const handleSearch = (value: string) => {
    if (value.trim()) {
      navigate(`/products?search=${encodeURIComponent(value.trim())}`);
    }
  };

  return (
    <div>
      {/* Hero 横幅 */}
      <div className="hero-banner">
        <h1>品质生活，轻松购得</h1>
        <p>发现精选好物，享受便捷购物体验</p>
        <Input.Search
          placeholder="搜索你想要的商品..."
          enterButton={<><SearchOutlined /> 搜索</>}
          size="large"
          onSearch={handleSearch}
          style={{ maxWidth: 520 }}
        />
      </div>

      {/* 分类导航 */}
      <div className="page-container" style={{ paddingTop: 0 }}>
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', marginBottom: 24, justifyContent: 'center' }}>
          {categories.map((cat) => (
            <span
              key={cat.key}
              onClick={() => setActiveCategory(cat.key)}
              style={{
                padding: '8px 20px',
                borderRadius: 20,
                cursor: 'pointer',
                fontSize: 15,
                background: activeCategory === cat.key ? '#1677ff' : '#fff',
                color: activeCategory === cat.key ? '#fff' : '#333',
                border: activeCategory === cat.key ? '1px solid #1677ff' : '1px solid #e8e8e8',
                transition: 'all 0.3s',
              }}
            >
              {cat.label}
            </span>
          ))}
        </div>

        {/* 商品列表 */}
        <Spin spinning={loading} size="large">
          {products.length > 0 ? (
            <>
              <div style={{ marginBottom: 16, color: '#666' }}>
                为您推荐 {activeCategory || '全部'}商品
              </div>
              <Row gutter={[16, 24]}>
                {products.map((product) => (
                  <Col key={product._id} xs={12} sm={8} md={6}>
                    <ProductCard product={product} />
                  </Col>
                ))}
              </Row>
            </>
          ) : (
            !loading && (
              <div className="empty-state">
                <Title level={4}>暂无商品</Title>
                <Paragraph type="secondary">该分类下还没有商品，去看看其他分类吧</Paragraph>
              </div>
            )
          )}
        </Spin>

        {/* 查看更多 */}
        {products.length > 0 && (
          <div style={{ textAlign: 'center', marginTop: 32 }}>
            <span
              onClick={() => navigate('/products')}
              style={{ color: '#1677ff', cursor: 'pointer', fontSize: 16 }}
            >
              查看全部商品 →
            </span>
          </div>
        )}
      </div>
    </div>
  );
