{"content": "import { useEffect, useState } from 'react';
import { Row, Col, Input, Select, Spin, Slider, Card, Empty, Pagination, Breadcrumb } from 'antd';
import { SearchOutlined, FilterOutlined } from '@ant-design/icons';
import { useSearchParams } from 'react-router-dom';
import ProductCard from '../components/ProductCard';
import { productApi } from '../services/api';
import type { Product } from '../types';

const { Option } = Select;

const categories = [
  { key: '', label: '全部分类' },
  { key: '电子产品', label: '电子产品' },
  { key: '服装鞋帽', label: '服装鞋帽' },
  { key: '图书文具', label: '图书文具' },
  { key: '家居生活', label: '家居生活' },
  { key: '食品饮料', label: '食品饮料' },
];

export default function ProductListPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [limit] = useState(12);

  const search = searchParams.get('search') || '';
  const category = searchParams.get('category') || '';
  const sort = searchParams.get('sort') || '';

  useEffect(() => {
    const fetchProducts = async () => {
      setLoading(true);
      try {
        const params: any = { page, limit };
        if (search) params.search = search;
        if (category) params.category = category;
        if (sort) params.sort = sort;
        const res = await productApi.getProducts(params);
        setProducts(res.data);
        setTotal(res.pagination.total);
      } catch {
        setProducts([]);
      } finally {
        setLoading(false);
      }
    };
    fetchProducts();
  }, [page, limit, search, category, sort]);

  const updateParams = (key: string, value: string) => {
    const params = new URLSearchParams(searchParams);
    if (value) {
      params.set(key, value);
    } else {
      params.delete(key);
    }
    params.delete('page');
    setSearchParams(params);
    setPage(1);
  };

  return (
    <div className="page-container">
      <Breadcrumb style={{ marginBottom: 16 }} items={[{ title: '首页', href: '/' }, { title: '全部商品' }]} />

      {/* 筛选栏 */}
      <Card style={{ marginBottom: 24 }}>
        <Row gutter={[16, 16]} align="middle">
          <Col xs={24} sm={8}>
            <Input.Search
              placeholder="搜索商品名称"
              prefix={<SearchOutlined />}
              defaultValue={search}
              onSearch={(val) => updateParams('search', val)}
              allowClear
            />
          </Col>
          <Col xs={12} sm={5}>
            <Select
              style={{ width: '100%' }}
              placeholder="选择分类"
              value={category || undefined}
              onChange={(val) => updateParams('category', val || '')}
              allowClear
            >
              {categories.map((c) => (
                <Option key={c.key} value={c.key}>
                  {c.label}
                </Option>
              ))}
            </Select>
          </Col>
          <Col xs={12} sm={5}>
            <Select
              style={{ width: '100%' }}
              placeholder="排序方式"
              value={sort || undefined}
              onChange={(val) => updateParams('sort', val || '')}
              allowClear
            >
              <Option value="">默认排序</Option>
              <Option value="price">价格 ↑</Option>
              <Option value="-price">价格 ↓</Option>
              <Option value="sales">销量 ↓</Option>
              <Option value="createdAt">最新</Option>
            </Select>
          </Col>
          <Col xs={24} sm={6}>
            <span style={{ color: '#666' }}>
              <FilterOutlined /> 共找到 {total} 件商品
            </span>
          </Col>
        </Row>
      </Card>

      {/* 商品列表 */}
      <Spin spinning={loading} size="large">
        {products.length > 0 ? (
          <>
            <Row gutter={[16, 24]}>
              {products.map((product) => (
                <Col key={product._id} xs={12} sm={8} md={6}>
                  <ProductCard product={product} />
                </Col>
              ))}
            </Row>
            <div style={{ textAlign: 'center', marginTop: 32 }}>
              <Pagination
                current={page}
                total={total}
                pageSize={limit}
                onChange={(p) => setPage(p)}
                showSizeChanger={false}
                showTotal={(t) => `共 ${t} 件商品`}
              />
            </div>
          </>
        ) : (
          !loading && (
            <Empty
              description={
                <span>
                  {search ? `未找到"${search}"相关商品` : '该分类下暂无商品'}
                </span>
              }
              style={{ padding: 60 }}
            />
          )
        )}
      </Spin>
    </div>
  );
}", "path": "D:\123\client\src\pages\ProductListPage.tsx"}

