  Breadcrumb,
  message,
  Typography,
  Divider,
  Descriptions,
} from 'antd';
import {
  ShoppingCartOutlined,
  ThunderboltOutlined,
  CheckCircleOutlined,
} from '@ant-design/icons';
import { productApi, cartApi } from '../services/api';
import { useAuthStore } from '../store/authStore';
import type { Product } from '../types';

const { Title, Paragraph, Text } = Typography;

export default function ProductDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { isAuthenticated } = useAuthStore();

  const [product, setProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(true);
  const [quantity, setQuantity] = useState(1);
  const [adding, setAdding] = useState(false);

  useEffect(() => {
    if (!id) return;
    const fetchProduct = async () => {
      setLoading(true);
      try {
        const res = await productApi.getProductById(id);
        setProduct(res.data);
      } catch {
        message.error('商品不存在');
        navigate('/products');
      } finally {
        setLoading(false);
      }
    };
    fetchProduct();
  }, [id, navigate]);

  const handleAddToCart = async () => {
    if (!isAuthenticated) {
      navigate('/login?redirect=' + encodeURIComponent(`/products/${id}`));
      return;
    }
    if (!product) return;

    setAdding(true);
    try {
      await cartApi.addToCart({ productId: product._id, quantity });
      message.success(`已添加 ${quantity} 件 "${product.name}" 到购物车`);
    } catch (error: any) {
      message.error(error.response?.data?.message || '添加失败');
    } finally {
      setAdding(false);
    }
  };

  const handleBuyNow = async () => {
    if (!isAuthenticated) {
      navigate('/login?redirect=' + encodeURIComponent(`/products/${id}`));
      return;
    }
    await handleAddToCart();
    navigate('/cart');
  };

  if (loading) {
    return (
      <div className="loading-center">
        <Spin size="large" tip="加载中..." />
      </div>
    );
  }

  if (!product) return null;

  const discount = product.originalPrice
    ? Math.round((1 - product.price / product.originalPrice) * 100)
    : 0;

  return (
    <div className="page-container">
      <Breadcrumb
        style={{ marginBottom: 16 }}
        items={[
          { title: '首页', href: '/' },
          { title: '全部商品', href: '/products' },
          { title: product.category, href: `/products?category=${encodeURIComponent(product.category)}` },
          { title: product.name },
        ]}
      />

      <Row gutter={[32, 24]}>
        {/* 商品图片 */}
        <Col xs={24} md={10}>
          <img
            alt={product.name}
            src={product.images?.[0] || 'https://picsum.photos/seed/default/400/400'}
            className="product-detail-image"
          />
          {product.images?.length > 1 && (
            <Row gutter={[8, 8]} style={{ marginTop: 8 }}>
              {product.images.map((img, index) => (
                <Col key={index} span={6}>
                  <img
                    src={img}
                    alt={`${product.name} ${index + 1}`}
                    style={{
                      width: '100%',
                      height: 80,
                      objectFit: 'cover',
                      borderRadius: 4,
                      cursor: 'pointer',
                      border: index === 0 ? '2px solid #1677ff' : '2px solid transparent',
                    }}
                  />
                </Col>
              ))}
            </Row>
          )}
        </Col>

        {/* 商品信息 */}
        <Col xs={24} md={14}>
          <div className="product-detail-info">
            <Title level={3}>{product.name}</Title>

            <div className="product-detail-price">
              <span className="current">¥{product.price.toFixed(2)}</span>
              {product.originalPrice > product.price && (
                <>
                  <span className="original">¥{product.originalPrice.toFixed(2)}</span>
                  <Tag color="red" style={{ marginLeft: 8 }}>-{discount}%</Tag>
                </>
              )}
            </div>

            <div className="product-detail-meta">
              <Rate disabled allowHalf value={product.rating} style={{ fontSize: 14 }} />
              <span style={{ marginLeft: 8 }}>{product.rating} 分</span>
            </div>

            <Divider />

            <Descriptions column={2} size="small">
              <Descriptions.Item label="商品分类">
                <Tag color="blue">{product.category}</Tag>
              </Descriptions.Item>
              <Descriptions.Item label="累计销量">{product.sales} 件</Descriptions.Item>
              <Descriptions.Item label="库存情况">
                {product.stock > 0 ? (
                  <span style={{ color: '#52c41a' }}>
                    <CheckCircleOutlined /> 有货 ({product.stock} 件)
                  </span>
                ) : (
                  <span style={{ color: '#ff4d4f' }}>缺货</span>
                )}
              </Descriptions.Item>
            </Descriptions>

            <Divider />

            {/* 数量选择 */}
            <div style={{ margin: '16px 0' }}>
              <Text strong style={{ marginRight: 12 }}>数量：</Text>
              <InputNumber
                min={1}
                max={product.stock}
                value={quantity}
                onChange={(val) => setQuantity(val || 1)}
              />
              <Text type="secondary" style={{ marginLeft: 8 }}>
                库存 {product.stock} 件
              </Text>
            </div>

            {/* 操作按钮 */}
            <div style={{ marginTop: 24 }}>
              <Button
                type="primary"
                size="large"
                icon={<ShoppingCartOutlined />}
                onClick={handleAddToCart}
                loading={adding}
                style={{ marginRight: 16 }}
                disabled={product.stock === 0}
              >
                加入购物车
              </Button>
              <Button
                type="primary"
                danger
                size="large"
                icon={<ThunderboltOutlined />}
                onClick={handleBuyNow}
                disabled={product.stock === 0}
              >
                立即购买
              </Button>
            </div>

            {/* 服务保障 */}
            <div style={{ marginTop: 24, padding: 16, background: '#f6ffed', borderRadius: 8 }}>
              <Text type="secondary">
                ✅ 正品保证 | 🚚 免费配送 | 🔄 7天无理由退换 | 🛡️ 售后保障
              </Text>
            </div>
          </div>
        </Col>
      </Row>

      {/* 商品描述 */}
      <Divider orientation="left" style={{ marginTop: 40 }}>
        商品详情
      </Divider>
      <div className="product-detail-desc">{product.description}</div>
    </div>
  );
}", "path": "D:\123\client\src\pages\ProductDetailPage.tsx"}

{"content": "import { useState } from 'react';
import { Card, Form, Input, Button, message, Typography, Divider } from 'antd';
import { MailOutlined, LockOutlined } from '@ant-design/icons';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { useAuthStore } from '../store/authStore';

const { Title, Text } = Typography;

export default function LoginPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { login, isLoading } = useAuthStore();
  const [form] = Form.useForm();

  const redirect = searchParams.get('redirect') || '/';

  const handleSubmit = async (values: { email: string; password: string }) => {
    try {
      await login(values.email, values.password);
      message.success('登录成功！');
      navigate(redirect, { replace: true });
    } catch (error: any) {
      message.error(error.message);
    }
  };

  // 快速登录填充
  const fillCredentials = (type: 'admin' | 'user') => {
    if (type === 'admin') {
      form.setFieldsValue({ email: 'admin@shopease.com', password: 'admin123' });
    } else {
      form.setFieldsValue({ email: 'user@shopease.com', password: 'user123' });
    }
  };

  return (
    <div className="auth-container">
      <Card className="auth-card">
        <div style={{ textAlign: 'center', marginBottom: 24 }}>
          <Title level={3}>欢迎回来</Title>
          <Text type="secondary">登录您的 ShopEase 账户</Text>
        </div>

        <Form form={form} layout="vertical" onFinish={handleSubmit} autoComplete="off">
          <Form.Item
            name="email"
            label="邮箱"
            rules={[
              { required: true, message: '请输入邮箱' },
              { type: 'email', message: '请输入有效的邮箱地址' },
            ]}
          >
            <Input prefix={<MailOutlined />} placeholder="请输入邮箱" size="large" />
          </Form.Item>

          <Form.Item
            name="password"
            label="密码"
            rules={[
              { required: true, message: '请输入密码' },
              { min: 6, message: '密码至少6位' },
            ]}
          >
            <Input.Password prefix={<LockOutlined />} placeholder="请输入密码" size="large" />
          </Form.Item>

          <Form.Item>
            <Button type="primary" htmlType="submit" size="large" block loading={isLoading}>
              登录
            </Button>
          </Form.Item>
        </Form>

        <Divider>
          <Text type="secondary" style={{ fontSize: 12 }}>快速体验</Text>
        </Divider>

        <div style={{ display: 'flex', gap: 8 }}>
          <Button size="small" onClick={() => fillCredentials('user')} block>
            测试用户
          </Button>
          <Button size="small" onClick={() => fillCredentials('admin')} block>
            管理员
          </Button>
        </div>

        <div style={{ textAlign: 'center', marginTop: 16 }}>
          <Text type="secondary">还没有账户？</Text>
          <Link to="/register">立即注册</Link>
        </div>
      </Card>
    </div>
  );
