{"content": "import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Table,
  Button,
  InputNumber,
  Typography,
  Empty,
  Card,
  Space,
  Popconfirm,
  message,
  Spin,
  Tag,
} from 'antd';
import {
  DeleteOutlined,
  ShoppingOutlined,
  ArrowLeftOutlined,
  ClearOutlined,
} from '@ant-design/icons';
import { cartApi } from '../services/api';
import type { CartItem as CartItemType, Product } from '../types';

const { Title, Text } = Typography;

export default function CartPage() {
  const navigate = useNavigate();
  const [cartItems, setCartItems] = useState<CartItemType[]>([]);
  const [loading, setLoading] = useState(true);
  const [updatingId, setUpdatingId] = useState<string | null>(null);

  const fetchCart = async () => {
    setLoading(true);
    try {
      const res = await cartApi.getCart();
      setCartItems(res.data);
    } catch {
      message.error('获取购物车失败');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCart();
  }, []);

  const handleQuantityChange = async (id: string, quantity: number) => {
    setUpdatingId(id);
    try {
      const res = await cartApi.updateCartItem(id, quantity);
      setCartItems((prev) =>
        prev.map((item) => (item._id === id ? res.data : item))
      );
    } catch (error: any) {
      message.error(error.response?.data?.message || '更新失败');
      fetchCart();
    } finally {
      setUpdatingId(null);
    }
  };

  const handleRemove = async (id: string) => {
    try {
      await cartApi.removeFromCart(id);
      setCartItems((prev) => prev.filter((item) => item._id !== id));
      message.success('已移除');
    } catch {
      message.error('移除失败');
    }
  };

  const handleClear = async () => {
    try {
      await cartApi.clearCart();
      setCartItems([]);
      message.success('购物车已清空');
    } catch {
      message.error('清空失败');
    }
  };

  const totalAmount = cartItems.reduce((sum, item) => {
    const product = item.productId as Product;
    return sum + (product?.price || 0) * item.quantity;
  }, 0);

  const totalCount = cartItems.reduce((sum, item) => sum + item.quantity, 0);

  const columns = [
    {
      title: '商品信息',
      dataIndex: 'productId',
      key: 'product',
      render: (product: any) => (
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <img
            src={product?.images?.[0] || ''}
            alt={product?.name}
            style={{
              width: 80,
              height: 80,
              objectFit: 'cover',
              borderRadius: 4,
              background: '#f0f0f0',
            }}
          />
          <div>
            <Text
              strong
              style={{ cursor: 'pointer' }}
              onClick={() => navigate(`/products/${product?._id}`)}
            >
              {product?.name || '商品已删除'}
            </Text>
            <div>
              {product?.category && <Tag color="blue">{product.category}</Tag>}
            </div>
          </div>
        </div>
      ),
    },
    {
      title: '单价',
      dataIndex: 'productId',
      key: 'price',
      width: 100,
      render: (product: any) => (
        <Text strong style={{ color: '#ff4d4f', fontSize: 16 }}>
          ¥{(product?.price || 0).toFixed(2)}
        </Text>
      ),
    },
    {
      title: '数量',
      dataIndex: 'quantity',
      key: 'quantity',
      width: 140,
      render: (quantity: number, record: CartItemType) => {
        const product = record.productId as Product;
        return (
          <InputNumber
            min={1}
            max={product?.stock || 99}
            value={quantity}
            onChange={(val) => val && handleQuantityChange(record._id, val)}
            loading={updatingId === record._id}
          />
        );
      },
    },
    {
      title: '小计',
      key: 'subtotal',
      width: 120,
      render: (_: any, record: CartItemType) => {
        const product = record.productId as Product;
        return (
          <Text strong style={{ color: '#ff4d4f', fontSize: 16 }}>
            ¥{((product?.price || 0) * record.quantity).toFixed(2)}
          </Text>
        );
      },
    },
    {
      title: '操作',
      key: 'action',
      width: 100,
      render: (_: any, record: CartItemType) => (
        <Popconfirm title="确定移除该商品？" onConfirm={() => handleRemove(record._id)}>
          <Button type="text" danger icon={<DeleteOutlined />}>
            删除
          </Button>
        </Popconfirm>
      ),
    },
  ];

  if (loading) {
    return (
      <div className="loading-center">
        <Spin size="large" />
      </div>
    );
  }

  return (
    <div className="page-container cart-container">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
        <Title level={3} style={{ margin: 0 }}>
          <ShoppingOutlined /> 购物车
        </Title>
        {cartItems.length > 0 && (
          <Popconfirm title="确定清空购物车？" onConfirm={handleClear}>
            <Button icon={<ClearOutlined />} danger>
              清空购物车
            </Button>
          </Popconfirm>
        )}
      </div>

      {cartItems.length > 0 ? (
        <>
          <Table
            dataSource={cartItems}
            columns={columns}
            rowKey="_id"
            pagination={false}
            locale={{ emptyText: <Empty description="购物车是空的" /> }}
          />

          <Card className="cart-summary" style={{ marginTop: 24 }}>
            <div className="cart-total">
              <Text style={{ fontSize: 16 }}>
                共 <Text strong>{totalCount}</Text> 件商品，合计：
              </Text>
              <span className="total-price">¥{totalAmount.toFixed(2)}</span>
            </div>

            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <Button icon={<ArrowLeftOutlined />} onClick={() => navigate('/products')}>
                继续购物
              </Button>
              <Button
                type="primary"
                size="large"
                icon={<ShoppingOutlined />}
                onClick={() => navigate('/orders')}
              >
                去结算
              </Button>
            </div>
          </Card>
        </>
      ) : (
        <Empty
          description={
            <div>
              <Title level={4}>购物车是空的</Title>
              <Text type="secondary">快去挑选心仪的商品吧</Text>
            </div>
          }
          style={{ padding: 60 }}
        >
          <Button type="primary" onClick={() => navigate('/products')}>
            去购物
          </Button>
        </Empty>
      )}
    </div>
  );
}", "path": "D:\123\client\src\pages\CartPage.tsx"}

{"content": "import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  List,
  Card,
  Tag,
  Typography,
  Empty,
  Spin,
  Button,
  Space,
  Pagination,
  Tabs,
} from 'antd';
import { OrderedListOutlined } from '@ant-design/icons';
import { orderApi } from '../services/api';
import type { Order } from '../types';
import dayjs from 'dayjs';

const { Title, Text } = Typography;

const statusColors: Record<string, string> = {
  pending: 'orange',
  paid: 'green',
  shipped: 'blue',
  delivered: 'cyan',
  cancelled: 'red',
};

const statusLabels: Record<string, string> = {
  pending: '待付款',
  paid: '已支付',
  shipped: '已发货',
  delivered: '已送达',
  cancelled: '已取消',
};

const tabItems = [
  { key: '', label: '全部' },
  { key: 'pending', label: '待付款' },
  { key: 'paid', label: '已支付' },
  { key: 'shipped', label: '已发货' },
  { key: 'delivered', label: '已完成' },
  { key: 'cancelled', label: '已取消' },
];

export default function OrderListPage() {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [status, setStatus] = useState('');
  const limit = 10;

  const fetchOrders = async () => {
    setLoading(true);
    try {
      const params: any = { page, limit };
      if (status) params.status = status;
      const res = await orderApi.getOrders(params);
      setOrders(res.data);
      setTotal(res.pagination.total);
    } catch {
      setOrders([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, [page, status]);

  const handleTabChange = (key: string) => {
    setStatus(key);
    setPage(1);
  };

  return (
    <div className="page-container" style={{ maxWidth: 800, margin: '0 auto' }}>
      <Title level={3} style={{ marginBottom: 24 }}>
        <OrderedListOutlined /> 我的订单
      </Title>

      <Tabs activeKey={status} onChange={handleTabChange} items={tabItems} />

      <Spin spinning={loading} size="large">
        {orders.length > 0 ? (
          <>
            <List
              dataSource={orders}
              renderItem={(order) => (
                <Card
                  key={order._id}
                  className="order-card"
                  onClick={() => navigate(`/orders/${order._id}`)}
                  style={{ cursor: 'pointer' }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 12 }}>
                    <Space>
                      <Text type="secondary">订单号：{order.orderNo}</Text>
                      <Text type="secondary">
                        {dayjs(order.createdAt).format('YYYY-MM-DD HH:mm')}
                      </Text>
                    </Space>
                    <Tag color={statusColors[order.status]}>
                      {statusLabels[order.status]}
                    </Tag>
                  </div>

                  {order.items.map((item, index) => (
                    <div
                      key={index}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 12,
                        padding: '8px 0',
                        borderBottom: index < order.items.length - 1 ? '1px solid #f0f0f0' : 'none',
                      }}
                    >
                      {item.image && (
                        <img
                          src={item.image}
                          alt={item.productName}
                          style={{
                            width: 60,
                            height: 60,
                            objectFit: 'cover',
                            borderRadius: 4,
                            background: '#f0f0f0',
                          }}
                        />
                      )}
                      <div style={{ flex: 1 }}>
                        <Text>{item.productName}</Text>
                        <div>
                          <Text type="secondary">
                            ¥{item.price.toFixed(2)} x {item.quantity}
                          </Text>
                        </div>
                      </div>
                      <Text strong>
                        ¥{(item.price * item.quantity).toFixed(2)}
                      </Text>
                    </div>
                  ))}

                  <div style={{ textAlign: 'right', marginTop: 12 }}>
                    <Text style={{ fontSize: 16 }}>
                      合计：<Text strong style={{ color: '#ff4d4f', fontSize: 18 }}>
