{"content": "import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Card,
  Descriptions,
  Tag,
  Typography,
  Spin,
  Button,
  Space,
  message,
  Divider,
  Steps,
  Table,
} from 'antd';
import {
  ArrowLeftOutlined,
  PayCircleOutlined,
  CloseCircleOutlined,
} from '@ant-design/icons';
import { orderApi } from '../services/api';
import type { Order } from '../types';
import dayjs from 'dayjs';

const { Title, Text } = Typography;

const statusColors: Record<string, string> = {
  pending: 'orange',
  paid: 'green',
  shipped: 'blue',
  delivered: 'cyan',
  cancelled: 'red',
};

const statusLabels: Record<string, string> = {
  pending: '待付款',
  paid: '已支付',
  shipped: '已发货',
  delivered: '已送达',
  cancelled: '已取消',
};

const orderSteps: Record<string, number> = {
  pending: 0,
  paid: 1,
  shipped: 2,
  delivered: 3,
  cancelled: -1,
};

export default function OrderDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);

  useEffect(() => {
    if (!id) return;
    const fetchOrder = async () => {
      setLoading(true);
      try {
        const res = await orderApi.getOrderById(id);
        setOrder(res.data);
      } catch {
        message.error('订单不存在');
        navigate('/orders');
      } finally {
        setLoading(false);
      }
    };
    fetchOrder();
  }, [id, navigate]);

  const handlePay = async () => {
    if (!order) return;
    setActionLoading(true);
    try {
      const res = await orderApi.payOrder(order._id);
      setOrder(res.data);
      message.success('支付成功！');
    } catch (error: any) {
      message.error(error.response?.data?.message || '支付失败');
    } finally {
      setActionLoading(false);
    }
  };

  const handleCancel = async () => {
    if (!order) return;
    setActionLoading(true);
    try {
      const res = await orderApi.cancelOrder(order._id);
      setOrder(res.data);
      message.success('订单已取消');
    } catch (error: any) {
      message.error(error.response?.data?.message || '取消失败');
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="loading-center">
        <Spin size="large" />
      </div>
    );
  }

  if (!order) return null;

  const currentStep = orderSteps[order.status] ?? -1;

  const columns = [
    {
      title: '商品',
      dataIndex: 'productName',
      key: 'productName',
      render: (name: string, record: any) => (
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          {record.image && (
            <img
              src={record.image}
              alt={name}
              style={{ width: 50, height: 50, objectFit: 'cover', borderRadius: 4 }}
            />
          )}
          <Text>{name}</Text>
        </div>
      ),
    },
    { title: '单价', dataIndex: 'price', key: 'price', render: (p: number) => `¥${p.toFixed(2)}` },
    { title: '数量', dataIndex: 'quantity', key: 'quantity' },
    {
      title: '小计',
      key: 'subtotal',
      render: (_: any, record: any) => `¥${(record.price * record.quantity).toFixed(2)}`,
    },
  ];

  return (
    <div className="page-container" style={{ maxWidth: 800, margin: '0 auto' }}>
      <Button
        icon={<ArrowLeftOutlined />}
        onClick={() => navigate('/orders')}
        style={{ marginBottom: 16 }}
      >
        返回订单列表
      </Button>

      <Card>
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginBottom: 24,
          }}
        >
          <Title level={4} style={{ margin: 0 }}>
            订单详情
          </Title>
          <Space>
            <Tag color={statusColors[order.status]} style={{ fontSize: 14, padding: '4px 12px' }}>
              {statusLabels[order.status]}
            </Tag>
          </Space>
        </div>

        {/* 订单进度 */}
        {order.status !== 'cancelled' ? (
          <Steps
            current={currentStep}
            items={[
              { title: '待付款' },
              { title: '已支付' },
              { title: '已发货' },
              { title: '已完成' },
            ]}
            style={{ marginBottom: 24 }}
          />
        ) : (
          <Steps
            current={1}
            direction="vertical"
            items={[{ title: '订单已取消', status: 'error', description: `取消时间：${dayjs(order.updatedAt).format('YYYY-MM-DD HH:mm')}` }]}
            style={{ marginBottom: 24 }}
          />
        )}

        <Descriptions bordered column={{ xs: 1, sm: 2 }} size="small">
          <Descriptions.Item label="订单编号">{order.orderNo}</Descriptions.Item>
          <Descriptions.Item label="订单状态">
            <Tag color={statusColors[order.status]}>{statusLabels[order.status]}</Tag>
          </Descriptions.Item>
          <Descriptions.Item label="下单时间">
            {dayjs(order.createdAt).format('YYYY-MM-DD HH:mm:ss')}
          </Descriptions.Item>
          {order.paidAt && (
            <Descriptions.Item label="支付时间">
              {dayjs(order.paidAt).format('YYYY-MM-DD HH:mm:ss')}
            </Descriptions.Item>
          )}
          <Descriptions.Item label="收货人">{order.shippingAddress.name}</Descriptions.Item>
          <Descriptions.Item label="联系电话">{order.shippingAddress.phone}</Descriptions.Item>
          <Descriptions.Item label="收货地址" span={2}>
            {order.shippingAddress.detail}
          </Descriptions.Item>
        </Descriptions>

        <Divider>商品清单</Divider>

        <Table
          dataSource={order.items}
          columns={columns}
          rowKey="productId"
          pagination={false}
          summary={() => (
            <Table.Summary>
              <Table.Summary.Row>
                <Table.Summary.Cell index={0} colSpan={3} align="right">
                  <Text strong style={{ fontSize: 16 }}>合计：</Text>
                </Table.Summary.Cell>
                <Table.Summary.Cell index={1}>
                  <Text strong style={{ color: '#ff4d4f', fontSize: 18 }}>
                    ¥{order.totalAmount.toFixed(2)}
                  </Text>
                </Table.Summary.Cell>
              </Table.Summary.Row>
            </Table.Summary>
          }}
        />

        {/* 操作按钮 */}
        {order.status === 'pending' && (
          <div style={{ textAlign: 'right', marginTop: 24 }}>
            <Space>
              <Button
                danger
                icon={<CloseCircleOutlined />}
                onClick={handleCancel}
                loading={actionLoading}
              >
                取消订单
              </Button>
              <Button
                type="primary"
                size="large"
                icon={<PayCircleOutlined />}
                onClick={handlePay}
                loading={actionLoading}
              >
                去支付 ¥{order.totalAmount.toFixed(2)}
              </Button>
            </Space>
          </div>
        )}
      </Card>
    </div>
  );
}", "path": "D:\123\client\src\pages\OrderDetailPage.tsx"}

{"content": "import { useState } from 'react';
import {
  Card,
  Form,
  Input,
  Button,
  Typography,
  message,
  Descriptions,
  Divider,
  Avatar,
  Space,
} from 'antd';
import { UserOutlined, EditOutlined } from '@ant-design/icons';
import { useAuthStore } from '../store/authStore';
import { authApi } from '../services/api';

const { Title, Text } = Typography;

export default function ProfilePage() {
  const { user, updateUser } = useAuthStore();
  const [editing, setEditing] = useState(false);
  const [loading, setLoading] = useState(false);
  const [form] = Form.useForm();

  if (!user) return null;

  const handleSave = async (values: { nickname: string }) => {
    setLoading(true);
    try {
      const res = await authApi.updateProfile({ nickname: values.nickname });
      updateUser(res.data);
      message.success('个人信息更新成功');
      setEditing(false);
    } catch (error: any) {
      message.error(error.response?.data?.message || '更新失败');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page-container" style={{ maxWidth: 700, margin: '0 auto' }}>
      <Card>
        <div style={{ textAlign: 'center', marginBottom: 24 }}>
          <Avatar size={80} icon={<UserOutlined />} style={{ backgroundColor: '#1677ff' }} />
          <Title level={4} style={{ marginTop: 12 }}>
            {user.nickname}
          </Title>
          <Text type="secondary">{user.email}</Text>
          <div style={{ marginTop: 8 }}>
            {user.role === 'admin' ? (
              <Button type="primary" ghost size="small">管理员</Button>
            ) : (
              <Button size="small" ghost>普通用户</Button>
            )}
          </div>
        </div>

        <Divider />

        {editing ? (
          <Form
            form={form}
            layout="vertical"
            initialValues={{ nickname: user.nickname }}
            onFinish={handleSave}
          >
            <Form.Item
              name="nickname"
              label="昵称"
              rules={[
                { required: true, message: '请输入昵称' },
                { min: 1, max: 30, message: '昵称长度1-30个字符' },
              ]}
            >
              <Input size="large" />
            </Form.Item>
            <Space>
              <Button type="primary" htmlType="submit" loading={loading}>
                保存
              </Button>
              <Button onClick={() => setEditing(false)}>取消</Button>
            </Space>
          </Form>
        ) : (
          <>
            <Descriptions column={1} size="large">
              <Descriptions.Item label="昵称">{user.nickname}</Descriptions.Item>
              <Descriptions.Item label="邮箱">{user.email}</Descriptions.Item>
              <Descriptions.Item label="角色">
                {user.role === 'admin' ? '管理员' : '普通用户'}
              </Descriptions.Item>
              <Descriptions.Item label="注册时间">
                {new Date(user.createdAt).toLocaleDateString('zh-CN')}
              </Descriptions.Item>
            </Descriptions>
            <Button
              type="primary"
              icon={<EditOutlined />}
              onClick={() => setEditing(true)}
              style={{ marginTop: 12 }}
            >
              编辑信息
            </Button>
          </>
        )}
      </Card>
    </div>
  );
