// 模拟 authStore
vi.mock('../../src/store/authStore', () => ({
  useAuthStore: vi.fn(),
}));

import { useAuthStore } from '../../src/store/authStore';

describe('AuthGuard 认证守卫', () => {
  it('已登录时应渲染子组件', () => {
    (useAuthStore as any).mockReturnValue({ isAuthenticated: true });
    render(
      <BrowserRouter>
        <AuthGuard>
          <div>受保护的内容</div>
        </AuthGuard>
      </BrowserRouter>
    );
    expect(screen.getByText('受保护的内容')).toBeInTheDocument();
  });

  it('未登录时应重定向到登录页', () => {
    (useAuthStore as any).mockReturnValue({ isAuthenticated: false });
    render(
      <MemoryRouter initialEntries={['/cart']}>
        <AuthGuard>
          <div>受保护的内容</div>
        </AuthGuard>
      </MemoryRouter>
    );
    expect(screen.queryByText('受保护的内容')).not.toBeInTheDocument();
  });
});

describe('AdminGuard 管理员守卫', () => {
  it('管理员应渲染子组件', () => {
    (useAuthStore as any).mockReturnValue({
      isAuthenticated: true,
      isAdmin: true,
    });
    render(
      <BrowserRouter>
        <AdminGuard>
          <div>管理内容</div>
        </AdminGuard>
      </BrowserRouter>
