{"content": "import { describe, it, expect, vi, beforeEach } from 'vitest';
import { useAuthStore } from '../../src/store/authStore';
import { authApi } from '../../src/services/api';

// 模拟 API
vi.mock('../../src/services/api', () => ({
  authApi: {
    login: vi.fn(),
    register: vi.fn(),
    getProfile: vi.fn(),
    updateProfile: vi.fn(),
  },
}));

describe('useAuthStore 认证状态管理', () => {
  beforeEach(() => {
    localStorage.clear();
    // 重置 store
    useAuthStore.setState({
      user: null,
      token: null,
      isAuthenticated: false,
      isLoading: false,
      isAdmin: false,
    });
  });

  it('初始状态应为未登录', () => {
    const state = useAuthStore.getState();
    expect(state.isAuthenticated).toBe(false);
    expect(state.user).toBeNull();
    expect(state.isAdmin).toBe(false);
  });

  it('login 成功后应更新状态', async () => {
    const mockUser = {
      _id: '1',
      email: 'test@test.com',
      nickname: '测试用户',
      role: 'user' as const,
      avatar: '',
      isActive: true,
      addresses: [],
      createdAt: '',
      updatedAt: '',
    };
    const mockResponse = {
      data: { token: 'test-token', user: mockUser },
    };
    (authApi.login as any).mockResolvedValue(mockResponse);

    await useAuthStore.getState().login('test@test.com', 'password');

    const state = useAuthStore.getState();
    expect(state.isAuthenticated).toBe(true);
    expect(state.token).toBe('test-token');
    expect(state.user?.email).toBe('test@test.com');
    expect(state.isAdmin).toBe(false);
    expect(localStorage.getItem('token')).toBe('test-token');
  });

  it('管理员登录后 isAdmin 应为 true', async () => {
    const mockAdmin = {
      _id: '2',
      email: 'admin@test.com',
      nickname: '管理员',
      role: 'admin' as const,
      avatar: '',
      isActive: true,
      addresses: [],
      createdAt: '',
      updatedAt: '',
    };
    const mockResponse = {
      data: { token: 'admin-token', user: mockAdmin },
    };
    (authApi.login as any).mockResolvedValue(mockResponse);

    await useAuthStore.getState().login('admin@test.com', 'admin123');

    const state = useAuthStore.getState();
    expect(state.isAuthenticated).toBe(true);
    expect(state.isAdmin).toBe(true);
    expect(state.user?.role).toBe('admin');
  });

  it('logout 应清除所有状态', () => {
    // 设置已登录状态
    useAuthStore.setState({
      user: { _id: '1', email: 'test@test.com', nickname: '测试', role: 'user', avatar: '', isActive: true, addresses: [], createdAt: '', updatedAt: '' },
      token: 'test-token',
      isAuthenticated: true,
      isAdmin: false,
    });
    localStorage.setItem('token', 'test-token');

    useAuthStore.getState().logout();

    const state = useAuthStore.getState();
    expect(state.isAuthenticated).toBe(false);
    expect(state.user).toBeNull();
    expect(state.token).toBeNull();
    expect(localStorage.getItem('token')).toBeNull();
  });

  it('login 失败应抛出错误', async () => {
    const error = {
      response: { data: { message: '邮箱或密码错误' } },
    };
    (authApi.login as any).mockRejectedValue(error);

    await expect(
      useAuthStore.getState().login('wrong@test.com', 'wrong')
    ).rejects.toThrow('邮箱或密码错误');

    const state = useAuthStore.getState();
    expect(state.isAuthenticated).toBe(false);
  });

  it('init 应从 localStorage 恢复状态', () => {
    const mockUser = JSON.stringify({
      _id: '1',
      email: 'test@test.com',
      nickname: '测试',
      role: 'user',
      avatar: '',
      isActive: true,
      addresses: [],
      createdAt: '',
      updatedAt: '',
    });
    localStorage.setItem('token', 'restored-token');
    localStorage.setItem('user', mockUser);

    useAuthStore.getState().init();

    const state = useAuthStore.getState();
    expect(state.isAuthenticated).toBe(true);
    expect(state.token).toBe('restored-token');
    expect(state.user?.email).toBe('test@test.com');
  });
});", "path": "D:\123\client\tests\store\authStore.test.ts"}

