{"content": "import request from 'supertest';
import app from '../index';
import { User } from '../models';

/** 辅助函数：创建管理员并获取Token */
async function getAdminToken(): Promise<string> {
  await User.create({
    email: 'admin@test.com',
    password: 'admin123',
    nickname: '管理员',
    role: 'admin',
  });
  const res = await request(app)
    .post('/api/auth/login')
    .send({ email: 'admin@test.com', password: 'admin123' });
  return res.body.data.token;
}

/** 辅助函数：创建普通用户并获取Token */
async function getUserToken(): Promise<string> {
  await User.create({
    email: 'user@test.com',
    password: 'user123',
    nickname: '普通用户',
  });
  const res = await request(app)
    .post('/api/auth/login')
    .send({ email: 'user@test.com', password: 'user123' });
  return res.body.data.token;
}

describe('Products API - 商品接口', () => {
  let adminToken: string;
  let userToken: string;

  beforeAll(async () => {
    adminToken = await getAdminToken();
    userToken = await getUserToken();
  });

  /** 获取商品列表 */
  describe('GET /api/products', () => {
    beforeEach(async () => {
      // 创建测试商品
      await request(app)
        .post('/api/products')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          name: '测试商品1',
          description: '描述1',
          price: 100,
          category: '电子产品',
          stock: 10,
        });
      await request(app)
        .post('/api/products')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          name: '测试商品2',
          description: '描述2',
          price: 200,
          category: '服装鞋帽',
          stock: 20,
        });
    });

    it('应返回商品列表（公开）', async () => {
      const res = await request(app).get('/api/products');
      expect(res.status).toBe(200);
      expect(res.body.success).toBe(true);
      expect(Array.isArray(res.body.data)).toBe(true);
    });

    it('应支持分页参数', async () => {
      const res = await request(app).get('/api/products?page=1&limit=1');
      expect(res.body.data.length).toBeLessThanOrEqual(1);
      expect(res.body.pagination).toBeDefined();
      expect(res.body.pagination.page).toBe(1);
      expect(res.body.pagination.limit).toBe(1);
    });

    it('应支持按分类筛选', async () => {
      const res = await request(app).get('/api/products?category=电子产品');
      expect(res.body.data).toHaveLength(1);
      expect(res.body.data[0].category).toBe('电子产品');
    });

    it('应支持按关键词搜索', async () => {
      const res = await request(app).get('/api/products?search=测试商品1');
      expect(res.body.data.length).toBeGreaterThanOrEqual(1);
    });

    it('应支持排序', async () => {
      const res = await request(app).get('/api/products?sort=price');
      const prices = res.body.data.map((p: any) => p.price);
      for (let i = 1; i < prices.length; i++) {
        expect(prices[i]).toBeGreaterThanOrEqual(prices[i - 1]);
      }
    });
  });

  /** 获取商品详情 */
  describe('GET /api/products/:id', () => {
    let productId: string;

    beforeEach(async () => {
      const res = await request(app)
        .post('/api/products')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          name: '详情测试商品',
          description: '这是一个测试商品详情',
          price: 99.99,
          category: '电子产品',
          stock: 50,
        });
      productId = res.body.data._id;
    });

    it('应返回商品详情', async () => {
      const res = await request(app).get(`/api/products/${productId}`);
      expect(res.status).toBe(200);
      expect(res.body.data.name).toBe('详情测试商品');
      expect(res.body.data.price).toBe(99.99);
    });

    it('不存在的商品应返回404', async () => {
      const res = await request(app).get('/api/products/000000000000000000000000');
      expect(res.status).toBe(404);
    });
  });

  /** 创建商品（管理员） */
  describe('POST /api/products', () => {
    it('管理员应能创建商品', async () => {
      const res = await request(app)
        .post('/api/products')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          name: '新商品',
          description: '新商品描述',
          price: 299,
          category: '电子产品',
          stock: 100,
        });

      expect(res.status).toBe(201);
      expect(res.body.data.name).toBe('新商品');
    });

    it('普通用户不能创建商品', async () => {
      const res = await request(app)
        .post('/api/products')
        .set('Authorization', `Bearer ${userToken}`)
        .send({
          name: '新商品',
          description: '描述',
          price: 99,
          category: '测试',
          stock: 10,
        });

      expect(res.status).toBe(403);
    });

    it('缺少必填字段应返回400', async () => {
      const res = await request(app)
        .post('/api/products')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ name: '不完整商品' });

      expect(res.status).toBe(400);
    });

    it('未认证不能创建商品', async () => {
      const res = await request(app)
        .post('/api/products')
        .send({ name: '商品', description: '描述', price: 99, category: '测试', stock: 10 });

      expect(res.status).toBe(401);
    });
  });

  /** 更新商品 */
  describe('PUT /api/products/:id', () => {
    let productId: string;

    beforeEach(async () => {
      const res = await request(app)
        .post('/api/products')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          name: '原商品名',
          description: '原描述',
          price: 100,
          category: '电子产品',
          stock: 10,
        });
      productId = res.body.data._id;
    });

    it('管理员应能更新商品', async () => {
      const res = await request(app)
        .put(`/api/products/${productId}`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ name: '更新后名称', price: 150 });

      expect(res.status).toBe(200);
      expect(res.body.data.name).toBe('更新后名称');
      expect(res.body.data.price).toBe(150);
    });
  });

  /** 删除商品 */
  describe('DELETE /api/products/:id', () => {
    let productId: string;

    beforeEach(async () => {
      const res = await request(app)
        .post('/api/products')
        .set('Authorization', `Bearer ${adminToken}`)
        .send({
          name: '待删除商品',
          description: '描述',
          price: 50,
          category: '测试',
          stock: 5,
        });
      productId = res.body.data._id;
    });

    it('管理员应能删除商品', async () => {
      const res = await request(app)
        .delete(`/api/products/${productId}`)
        .set('Authorization', `Bearer ${adminToken}`);

      expect(res.status).toBe(200);
      expect(res.body.success).toBe(true);
    });

    it('普通用户不能删除商品', async () => {
      const res = await request(app)
        .delete(`/api/products/${productId}`)
        .set('Authorization', `Bearer ${userToken}`);

      expect(res.status).toBe(403);
    });
  });
});", "path": "D:\123\server\src\__tests__\products.test.ts"}

