{"content": "import request from 'supertest';
import app from '../index';
import { User } from '../models';

async function setupTestData() {
  // 管理员登录
  await User.create({
    email: 'admin-order@test.com', password: 'admin123', nickname: '管理员', role: 'admin',
  });
  const adminLogin = await request(app)
    .post('/api/auth/login')
    .send({ email: 'admin-order@test.com', password: 'admin123' });
  const adminToken = adminLogin.body.data.token;

  // 创建商品
  const prodRes = await request(app)
    .post('/api/products')
    .set('Authorization', `Bearer ${adminToken}`)
    .send({ name: '订单测试商品', description: '测试', price: 100, category: '电子产品', stock: 50 });
  const productId = prodRes.body.data._id;

  // 创建商品2
  const prodRes2 = await request(app)
    .post('/api/products')
    .set('Authorization', `Bearer ${adminToken}`)
    .send({ name: '订单测试商品2', description: '测试2', price: 200, category: '服装鞋帽', stock: 30 });
  const productId2 = prodRes2.body.data._id;

  // 创建用户
  await User.create({
    email: 'order@test.com', password: 'password123', nickname: '订单测试',
  });
  const loginRes = await request(app)
    .post('/api/auth/login')
    .send({ email: 'order@test.com', password: 'password123' });
  const token = loginRes.body.data.token;

  return { token, adminToken, productId, productId2 };
}

describe('Orders API - 订单接口', () => {
  let token: string;
  let adminToken: string;
  let productId: string;
  let productId2: string;

  beforeAll(async () => {
    const data = await setupTestData();
    token = data.token;
    adminToken = data.adminToken;
    productId = data.productId;
    productId2 = data.productId2;
  });

  /** 创建订单 */
  describe('POST /api/orders', () => {
    it('应成功创建订单', async () => {
      const res = await request(app)
        .post('/api/orders')
        .set('Authorization', `Bearer ${token}`)
        .send({
          items: [
            { productId, quantity: 2 },
            { productId: productId2, quantity: 1 },
          ],
          shippingAddress: {
            name: '张三',
            phone: '13800138000',
            detail: '广东省深圳市南山区科技园',
          },
        });

      expect(res.status).toBe(201);
      expect(res.body.success).toBe(true);
      expect(res.body.data).toHaveProperty('orderNo');
      expect(res.body.data.totalAmount).toBe(400); // 100*2 + 200*1
      expect(res.body.data.status).toBe('pending');
      expect(res.body.data.items).toHaveLength(2);
    });

    it('未认证不能创建订单', async () => {
      const res = await request(app)
        .post('/api/orders')
        .send({ items: [{ productId, quantity: 1 }], shippingAddress: { name: '测试', phone: '123', detail: '地址' } });

      expect(res.status).toBe(401);
    });

    it('空商品列表应返回400', async () => {
      const res = await request(app)
        .post('/api/orders')
        .set('Authorization', `Bearer ${token}`)
        .send({ items: [], shippingAddress: { name: '测试', phone: '123', detail: '地址' } });

      expect(res.status).toBe(400);
    });

    it('缺少收货地址应返回400', async () => {
      const res = await request(app)
        .post('/api/orders')
        .set('Authorization', `Bearer ${token}`)
        .send({ items: [{ productId, quantity: 1 }] });

      expect(res.status).toBe(400);
    });
  });

  /** 获取订单列表 */
  describe('GET /api/orders', () => {
    beforeEach(async () => {
      await request(app)
        .post('/api/orders')
        .set('Authorization', `Bearer ${token}`)
        .send({
          items: [{ productId, quantity: 1 }],
          shippingAddress: { name: '李四', phone: '13900139000', detail: '北京市朝阳区' },
        });
    });

    it('应返回用户订单列表', async () => {
      const res = await request(app)
        .get('/api/orders')
        .set('Authorization', `Bearer ${token}`);

      expect(res.status).toBe(200);
      expect(res.body.success).toBe(true);
      expect(Array.isArray(res.body.data)).toBe(true);
      expect(res.body.data.length).toBeGreaterThanOrEqual(1);
    });
  });

  /** 模拟支付 */
  describe('PUT /api/orders/:id/pay', () => {
    let orderId: string;

    beforeEach(async () => {
      const res = await request(app)
        .post('/api/orders')
        .set('Authorization', `Bearer ${token}`)
        .send({
          items: [{ productId, quantity: 1 }],
          shippingAddress: { name: '王五', phone: '13700137000', detail: '上海市浦东新区' },
        });
      orderId = res.body.data._id;
    });

    it('应成功支付待付款订单', async () => {
      const res = await request(app)
        .put(`/api/orders/${orderId}/pay`)
        .set('Authorization', `Bearer ${token}`);

      expect(res.status).toBe(200);
      expect(res.body.data.status).toBe('paid');
      expect(res.body.data).toHaveProperty('paidAt');
    });
  });

  /** 取消订单 */
  describe('PUT /api/orders/:id/cancel', () => {
    let orderId: string;

    beforeEach(async () => {
      const res = await request(app)
        .post('/api/orders')
        .set('Authorization', `Bearer ${token}`)
        .send({
          items: [{ productId, quantity: 1 }],
          shippingAddress: { name: '赵六', phone: '13600136000', detail: '杭州市西湖区' },
        });
      orderId = res.body.data._id;
    });

    it('应取消待付款订单', async () => {
      const res = await request(app)
        .put(`/api/orders/${orderId}/cancel`)
        .set('Authorization', `Bearer ${token}`);

      expect(res.status).toBe(200);
      expect(res.body.data.status).toBe('cancelled');
    });

    it('已支付订单不能取消', async () => {
      await request(app)
        .put(`/api/orders/${orderId}/pay`)
        .set('Authorization', `Bearer ${token}`);

      const res = await request(app)
        .put(`/api/orders/${orderId}/cancel`)
        .set('Authorization', `Bearer ${token}`);

      expect(res.status).toBe(400);
    });
  });

  /** 管理员更新订单状态 */
  describe('PUT /api/orders/:id/status', () => {
    let orderId: string;

    beforeEach(async () => {
      // 创建并支付订单
      const createRes = await request(app)
        .post('/api/orders')
        .set('Authorization', `Bearer ${token}`)
        .send({
          items: [{ productId, quantity: 1 }],
          shippingAddress: { name: '测试', phone: '13500135000', detail: '广州市天河区' },
        });
      orderId = createRes.body.data._id;
      await request(app)
        .put(`/api/orders/${orderId}/pay`)
        .set('Authorization', `Bearer ${token}`);
    });

    it('应更新订单状态为已发货', async () => {
      const res = await request(app)
        .put(`/api/orders/${orderId}/status`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ status: 'shipped' });

      expect(res.status).toBe(200);
      expect(res.body.data.status).toBe('shipped');
    });

    it('无效状态应返回400', async () => {
      const res = await request(app)
        .put(`/api/orders/${orderId}/status`)
        .set('Authorization', `Bearer ${adminToken}`)
        .send({ status: 'invalid_status' });

      expect(res.status).toBe(400);
    });
  });
});", "path": "D:\123\server\src\__tests__\orders.test.ts"}

