{"content": "import express from 'express';
import cors from 'cors';
import { config } from './config';
import { connectDB } from './config/database';
import authRoutes from './routes/auth';
import productRoutes from './routes/products';
import cartRoutes from './routes/cart';
import orderRoutes from './routes/orders';

const app = express();

/** 中间件 */
app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

/** 健康检查 */
app.get('/api/health', (_req, res) => {
  res.json({
    success: true,
    message: 'ShopEase 商城服务运行中',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

/** 路由注册 */
app.use('/api/auth', authRoutes);
app.use('/api/products', productRoutes);
app.use('/api/cart', cartRoutes);
app.use('/api/orders', orderRoutes);

/** 404 处理 */
app.use((_req, res) => {
  res.status(404).json({
    success: false,
    message: '请求的资源不存在',
  });
});

/** 全局错误处理 */
app.use((err: Error, _req: express.Request, res: express.Response, _next: express.NextFunction) => {
  console.error('服务器错误:', err);
  res.status(500).json({
    success: false,
    message: config.isDev ? err.message : '服务器内部错误',
  });
});

/** 启动服务器（非测试环境下）*/
if (!config.isTest) {
  const startServer = async () => {
    await connectDB();
    app.listen(config.port, () => {
      console.log(`\n🛒  ShopEase 商城服务已启动`);
      console.log(`📡  API地址: http://localhost:${config.port}/api`);
      console.log(`🏥 健康检查: http://localhost:${config.port}/api/health\n`);
    });
  };
  startServer();
}

export default app;", "path": "D:\123\server\src\index.ts"}
